using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.FNZ.DocumentosTransaccion;using GraphApi.Services.FNZ.DocumentosTransaccion;namespace GraphApi.Controllers.FNZ.DocumentosTransaccion{    /// <summary>    /// Gestión de DocumentosTransaccions: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("FNZ/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre DocumentosTransaccions")]    public class DocumentosTransaccionController : Controller    {        private readonly IDocumentosTransaccionService _objService;        public DocumentosTransaccionController(IDocumentosTransaccionService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los DocumentosTransaccions, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="documentoTransaccionID">DocumentoTransaccionID</param>        /// <param name="transaccionID">TransaccionID</param>        /// <param name="documentoID">DocumentoID</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de DocumentosTransaccions</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar DocumentosTransaccions",            Description = "Devuelve DocumentosTransaccions aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadDocumentosTransaccion>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadDocumentosTransaccion>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? documentoTransaccionID,            [FromQuery] int? transaccionID,            [FromQuery] int? documentoID,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetDocumentosTransaccionsDynamic(                documentoTransaccionID,                 transaccionID,                 documentoID,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo DocumentosTransaccion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del DocumentosTransaccion a crear.</param>        /// <returns>El DocumentosTransaccion recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear DocumentosTransaccions",            Description = "Inserta un nuevo DocumentosTransaccion en la base de datos."        )]        [ProducesResponseType(typeof(clReadDocumentosTransaccion), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadDocumentosTransaccion>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateDocumentosTransaccion objInput)        {            var vCreated = await _objService.CreateDocumentosTransaccion(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de DocumentosTransaccion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del DocumentosTransaccion.</param>        /// <returns>El DocumentosTransaccion actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar DocumentosTransaccions",            Description = "Actualiza uno o varios campos de DocumentosTransaccion existente."        )]        [ProducesResponseType(typeof(clReadDocumentosTransaccion), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadDocumentosTransaccion>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateDocumentosTransaccion objInput)        {            var vUpdated = await _objService.UpdateDocumentosTransaccion(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un DocumentosTransaccion por su ID.        /// </summary>        [HttpDelete("{nDocumentosTransaccionID:int}")]        [SwaggerOperation(            Summary = "Eliminar DocumentosTransaccion",            Description = "Borra un DocumentosTransaccion si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nDocumentosTransaccionID)        {            var success = await _objService.DeleteDocumentosTransaccion(nDocumentosTransaccionID);            return success ? NoContent() : NotFound();        }    }}